package com.ecommerce.order.service; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*; @RestController @RequestMapping("/api/orders") public class OrderController { final OrderRepository repo; OrderController(OrderRepository r){repo=r;} record Req(@NotNull UUID customerId,@NotNull @Positive BigDecimal total){} @PostMapping Order create(@RequestBody Req x){Order o=new Order();o.setCustomerId(x.customerId());o.setTotal(x.total());return repo.save(o);} @GetMapping("/{id}") Order get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Order not found"));} @GetMapping("/customer/{customerId}") List<Order> mine(@PathVariable UUID customerId){return repo.findByCustomerIdOrderByCreatedAtDesc(customerId);} @PatchMapping("/{id}/status") Order status(@PathVariable UUID id,@RequestParam Order.Status value){Order o=get(id);o.setStatus(value);return repo.save(o);} }